public class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> groupedByDomain = new Map<String, List<Contact>>();

        if (accountIds == null) {
            return groupedByDomain;
        }

        List<Id> accountIdsToQuery = new List<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountIdsToQuery.add(accountId);
            }
        }

        if (accountIdsToQuery.isEmpty()) {
            return groupedByDomain;
        }

        Integer batchSize = 1000;

        for (Integer i = 0; i < accountIdsToQuery.size(); i += batchSize) {
            Integer end = Math.min(i + batchSize, accountIdsToQuery.size());
            List<Id> batch = new List<Id>(accountIdsToQuery.subList(i, end));

            List<Contact> contacts = [
                SELECT Id, Email, AccountId
                FROM Contact
                WITH SECURITY_ENFORCED
                WHERE AccountId IN :batch AND Email != null
            ];

            for (Contact contact : contacts) {
                String email = contact.Email;

                if (email == null) {
                    continue;
                }

                String normalizedEmail = email.trim();

                if (normalizedEmail.length() == 0) {
                    continue;
                }

                Integer atPosition = normalizedEmail.lastIndexOf('@');

                if (atPosition == -1 || atPosition == normalizedEmail.length() - 1) {
                    continue;
                }

                String domain = normalizedEmail.substring(atPosition + 1).trim();

                if (domain.length() == 0) {
                    continue;
                }

                domain = domain.toLowerCase();

                if (!groupedByDomain.containsKey(domain)) {
                    groupedByDomain.put(domain, new List<Contact>());
                }

                groupedByDomain.get(domain).add(contact);
            }
        }

        return groupedByDomain;
    }
}
