public class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> groupedByDomain = new Map<String, List<Contact>>();
        if (accountIds == null || accountIds.isEmpty()) {
            return groupedByDomain;
        }

        List<Id> allAccountIds = new List<Id>(accountIds);
        final Integer batchSize = 1000;

        for (Integer index = 0; index < allAccountIds.size(); index += batchSize) {
            Integer endIndex = Math.min(index + batchSize, allAccountIds.size());
            List<Id> accountIdsBatch = new List<Id>(allAccountIds.subList(index, endIndex));
            List<Contact> contacts = [
                SELECT Id, Email, AccountId
                FROM Contact
                WITH SECURITY_ENFORCED
                WHERE AccountId IN :accountIdsBatch AND Email != null
            ];

            for (Contact contact : contacts) {
                String email = contact.Email;
                if (String.isBlank(email)) {
                    continue;
                }

                String trimmedEmail = email.trim();
                Integer atPosition = trimmedEmail.lastIndexOf('@');
                if (atPosition == -1 || atPosition == trimmedEmail.length() - 1) {
                    continue;
                }

                String domain = trimmedEmail.substring(atPosition + 1).toLowerCase();
                if (String.isBlank(domain)) {
                    continue;
                }

                if (!groupedByDomain.containsKey(domain)) {
                    groupedByDomain.put(domain, new List<Contact>());
                }
                groupedByDomain.get(domain).add(contact);
            }
        }

        return groupedByDomain;
    }
}
```

