public with sharing class ContactLookupAction {
    @InvocableMethod(
        Label='Find Contact by Email',
        Description='Finds an existing Contact by email address, matching case-insensitively and trimming input whitespace.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null) {
            return results;
        }

        Set<String> uniqueEmails = new Set<String>();

        for (Request req : requests) {
            if (req != null && req.email != null) {
                String normalizedEmail = req.email.trim().toLowerCase();
                if (normalizedEmail.length() > 0) {
                    uniqueEmails.add(normalizedEmail);
                }
            }
        }

        Map<String, Contact> earliestByNormalizedEmail = new Map<String, Contact>();

        if (!uniqueEmails.isEmpty()) {
            List<String> emailsToQuery = new List<String>(uniqueEmails);

            for (Contact c : [
                SELECT Id, CreatedDate
                FROM Contact
                WHERE LOWER(Email) IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (c.Email != null) {
                    String normalizedEmail = c.Email.toLowerCase();

                    if (!earliestByNormalizedEmail.containsKey(normalizedEmail)) {
                        earliestByNormalizedEmail.put(normalizedEmail, c);
                    }
                }
            }
        }

        for (Request req : requests) {
            Result r = new Result();
            r.found = false;
            r.contactId = null;

            if (req != null && req.email != null) {
                String normalizedEmail = req.email.trim().toLowerCase();

                if (normalizedEmail.length() > 0) {
                    Contact c = earliestByNormalizedEmail.get(normalizedEmail);

                    if (c != null) {
                        r.contactId = c.Id;
                        r.found = true;
                    }
                }
            }

            results.add(r);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(
            Label='Email',
