public with sharing class ContactLookupAction {
    @InvocableMethod(Label='Find Contact by Email', Description='Finds an existing Contact by email address, case-insensitively.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null) {
            return results;
        }

        Set<String> uniqueEmails = new Set<String>();
        for (Request req : requests) {
            if (req != null && req.email != null) {
                String normalized = req.email.trim().toLowerCase();
                if (normalized.length() > 0) {
                    uniqueEmails.add(normalized);
                }
            }
        }

        Map<String, Contact> earliestByNormalizedEmail = new Map<String, Contact>();
        if (!uniqueEmails.isEmpty()) {
            List<String> emailsToQuery = new List<String>(uniqueEmails);
            for (Contact c : [
                SELECT Id, CreatedDate
                FROM Contact
                WHERE LOWER(Email) IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (c.Email != null) {
                    String normalized = c.Email.toLowerCase();
                    if (!earliestByNormalizedEmail.containsKey(normalized)) {
                        earliestByNormalizedEmail.put(normalized, c);
                    }
                }
            }
        }

        for (Request req : requests) {
            Result r = new Result();
            r.found = false;
            r.contactId = null;
            if (req != null && req.email != null) {
                String normalized = req.email.trim().toLowerCase();
                if (normalized.length() > 0) {
                    Contact c = earliestByNormalizedEmail.get(normalized);
                    if (c != null) {
                        r.contactId = c.Id;
                        r.found = true;
                    }
                }
            }
            results.add(r);
        }
        return results;
    }

    public class Request {
        @InvocableVariable(Label='Email', Description='Email address to look up.', Required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(Label='Contact ID', Description='Id of the matching Contact, if found.')
        public Id contactId;

        @InvocableVariable(Label='Found', Description='Whether a Contact was found.')
        public Boolean found;
    }
}

