public class OrderPayloadParser {

    // ─── Public inner classes ───────────────────────────────────────────────

    public class Order {
        public String orderNumber;
        public Date   orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    // ─── Public API ─────────────────────────────────────────────────────────

    public static Order parse(String body) {
        if (body == null || String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank');
        }

        // Deserialize and verify top-level is a JSON object
        Map<String, Object> root;
        try {
            Object parsed = JSON.deserializeUntyped(body);
            if (parsed == null || !(parsed instanceof Map)) {
                throw new PayloadException('Request body is not a JSON object');
            }
            root = (Map<String, Object>) parsed;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + (e.getMessage() != null ? e.getMessage() : 'parse error'));
        }

        // --- number ---
        Object numberObj = root.get('number');
        if (numberObj == null) {
            throw new PayloadException('Missing required field: number');
        }
        String orderNumber = String.valueOf(numberObj);
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Field number is blank');
        }

        // --- date ---
        Date orderDate = null;
        Object dateObj = root.get('date');
        if (dateObj != null) {
            try {
                orderDate = Date.valueOf(String.valueOf(dateObj));
            } catch (Exception e) {
                throw new PayloadException('Invalid date value: ' + (e.getMessage() != null ? e.getMessage() : 'parse error'));
            }
        }

        // --- currency ---
        Object currencyObj = root.get('currency');
        String currencyCode = (currencyObj == null) ? null : String.valueOf(currencyObj);

        // --- customer (optional) ---
        String customerEmail = null;
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map) {
            Map<String, Object> custMap = (Map<String, Object>) customerObj;
            Object emailObj = custMap.get('email');
            if (emailObj != null) {
                customerEmail = String.valueOf(emailObj);
            }
        }

        // --- lines ---
        List<Line> lines = new List<Line>();
        Object linesObj = root.get('lines');
        if (linesObj instanceof List) {
            List<Object> rawLines = (List<Object>) linesObj;
            for (Object rawLine : rawLines) {
                if (rawLine == null || !(rawLine instanceof Map)) {
                    throw new PayloadException('Each line must be a JSON object');
                }
                lines.add(buildLine((Map<String, Object>) rawLine));
            }
        }

        // --- total ---
        Decimal total = 0;
        for (Line ln : lines) {
            total += ln.lineTotal;
        }

        Order order = new Order();
        order.orderNumber  = orderNumber;
        order.orderDate    = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines        = lines;
        order.total        = total;
        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object> {
            'number'    => order.orderNumber,
            'status'    => 'RECEIVED',
            'lineCount' => order.lines.size(),
            'total'     => order.total
        };
        return JSON.serialize(ack);
    }

    // ─── Private helpers ────────────────────────────────────────────────────

    private static Line buildLine(Map<String, Object> m) {

        // sku
        Object skuObj = m.get('sku');
        if (skuObj == null || String.isBlank(String.valueOf(skuObj))) {
            throw new PayloadException('Line is missing sku');
        }

        // quantity
        Object qtyObj = m.get('quantity');
        if (qtyObj == null) {
            throw new PayloadException('Line is missing quantity');
        }
        Integer quantity;
        if (qtyObj instanceof Integer) {
            quantity = (Integer) qtyObj;
        } else if (qtyObj instanceof Decimal) {
            quantity = (Integer) qtyObj;
        } else {
            throw new PayloadException('Line quantity must be a number');
        }
        if (quantity <= 0) {
            throw new PayloadException('Line quantity must be positive');
        }

        // unitPrice
        Object priceObj = m.get('unitPrice');
        if (priceObj == null) {
            throw new PayloadException('Line is missing unitPrice');
        }
        Decimal unitPrice;
        if (priceObj instanceof Integer) {
            unitPrice = (Decimal) priceObj;
        } else if (priceObj instanceof Decimal) {
            unitPrice = (Decimal) priceObj;
        } else {
            throw new PayloadException('Line unitPrice must be a number');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Line unitPrice must not be negative');
        }

        // discount (missing / null → 0)
        Object discObj = m.get('discount');
        Decimal discount = 0;
        if (discObj != null) {
            if (discObj instanceof Integer) {
                discount = (Decimal) discObj;
            } else if (discObj instanceof Decimal) {
                discount = (Decimal) discObj;
            } else {
                throw new PayloadException('Line discount must be a number');
            }
        }

        // lineTotal = quantity × unitPrice × (1 − discount), rounded half-up to 2 dp
        Decimal rawTotal = (Decimal) quantity * unitPrice * ((Decimal) 1 - discount);
        Decimal lineTotal = roundHalfUp2dp(rawTotal);

        Line line = new Line();
        line.sku        = String.valueOf(skuObj);
        line.quantity   = quantity;
        line.unitPrice  = unitPrice;
        line.discount   = discount;
        line.lineTotal  = lineTotal;
        return line;
    }

    /**
     * Rounds a Decimal to 2 decimal places using "half up" (ties round toward
     * positive infinity).  Because line totals are always non-negative in this
     * domain, the negative branch is included only for defensive completeness.
     */
    private static Decimal roundHalfUp2dp(Decimal value) {
        if (value >= 0) {
            Double scaled = (Double) value * 100 + 0.5;
            return (Decimal) (Math.floor(scaled) / 100);
        } else {
            Double scaled = (Double) value * 100 - 0.5;
            return (Decimal) (Math.ceil(scaled) / 100);
        }
    }
}
