    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON in request body.');
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Request body must be a JSON object.');
        }

        Map<String, Object> map = (Map<String, Object>) root;

        // --- number (required) ---
        if (!map.containsKey('number') || map.get('number') == null) {
            throw new PayloadException('Missing "number".');
        }
        Object numObj = map.get('number');
        if (!(numObj instanceof String) || String.isBlank((String) numObj)) {
            throw new PayloadException('"number" must be a non-blank string.');
        }

        Order order = new Order();
        order.orderNumber = (String) numObj;

        // --- date ---
        if (map.containsKey('date') && map.get('date') != null && map.get('date') instanceof String) {
            try {
                order.orderDate = Date.valueOf((String) map.get('date'));
            } catch (Exception e) {
                order.orderDate = null;
            }
        }

        // --- currency ---
        if (map.containsKey('currency') && map.get('currency') != null && map.get('currency') instanceof String) {
            order.currencyCode = (String) map.get('currency');
        }

        // --- customer ---
        if (map.containsKey('customer') && map.get('customer') != null && map.get('customer') instanceof Map<String, Object>) {
            Map<String, Object> custMap = (Map<String, Object>) map.get('customer');
            if (custMap.containsKey('email') && custMap.get('email') != null && custMap.get('email') instanceof String) {
                order.customerEmail = (String) custMap.get('email');
            }
        }

        // --- lines ---
        order.lines = new List<Line>();
        Decimal total = 0;

        if (map.containsKey('lines') && map.get('lines') != null && map.get('lines') instanceof List<Object>) {
            List<Object> linesList = (List<Object>) map.get('lines');
            for (Integer i = 0; i < linesList.size(); i++) {
                Object lineObj = linesList[i];
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Line at index ' + i + ' is not an object.');
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                // sku (required)
                if (!lineMap.containsKey('sku') || lineMap.get('sku') == null || !(lineMap.get('sku') instanceof String) || String.isBlank((String) lineMap.get('sku'))) {
                    throw new PayloadException('Missing "sku" in line ' + i + '.');
                }

                // quantity (required, positive)
                if (!lineMap.containsKey('quantity') || lineMap.get('quantity') == null) {
                    throw new PayloadException('Missing "quantity" in line ' + i + '.');
                }
                Object qtyObj = lineMap.get('quantity');
                Integer qty;
                if (qtyObj instanceof Integer) {
                    qty = (Integer) qtyObj;
                } else if (qtyObj instanceof Double) {
                    qty = (Integer) (Double) qtyObj;
                } else {
                    throw new PayloadException('Invalid "quantity" in line ' + i + '.');
                }
                if (qty <= 0) {
                    throw new PayloadException('Non-positive "quantity" in line ' + i + '.');
                }

                // unitPrice (required, non-negative)
                if (!lineMap.containsKey('unitPrice') || lineMap.get('unitPrice') == null) {
                    throw new PayloadException('Missing "unitPrice" in line ' + i + '.');
                }
                Object priceObj = lineMap.get('unitPrice');
                Decimal price;
                if (priceObj instanceof Integer) {
                    price = (Decimal) (Integer) priceObj;
                } else if (priceObj instanceof Double) {
                    price = (Decimal) (Double) priceObj;
                } else {
                    throw new PayloadException('Invalid "unitPrice" in line ' + i + '.');
                }
                if (price < 0) {
                    throw new PayloadException('Negative "unitPrice" in line ' + i + '.');
                }

                // discount (optional, defaults to 0)
                Decimal disc = 0;
                if (lineMap.containsKey('discount') && lineMap.get('discount') != null) {
                    Object discObj = lineMap.get('discount');
                    if (discObj instanceof Integer) {
                        disc = (Decimal) (Integer) discObj;
                    } else if (discObj instanceof Double) {
                        disc = (Decimal) (Double) discObj;
                    }
                }

                Line line = new Line();
                line.sku = (String) lineMap.get('sku');
                line.quantity = qty;
                line.unitPrice = price;
                line.discount = disc;

                // lineTotal = quantity * unitPrice * (1 - discount), rounded half-up to 2 dp
                Decimal raw = (Decimal) qty * price * ((Decimal) 1 - disc);
                line.lineTotal = (Decimal) System.Math.round(raw.doubleValue() * 100) / 100;

                order.lines.add(line);
                total += line.lineTotal;
            }
        }

        order.total = total;
        return order;
    }

    public static String toAcknowledgement(Order order) {
        Ack ack = new Ack();
        ack.number = order.orderNumber;
        ack.status = 'RECEIVED';
        ack.lineCount = order.lines.size();
        ack.total = order.total;
        return JSON.serialize(ack);
    }
}
