        }

        Schema.SObjectField fieldToken = findFieldCaseInsensitive(
            objDescribe.fieldsMap, fieldApiName
        );

        if (fieldToken == null) {
            throw new PicklistServiceException(
                'Field \'' + fieldApiName + '\' does not exist on object \'' + objectApiName + '\'.'
            );
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();

        if (fieldDescribe.getType() != Schema.DisplayType.PICKLIST
            && fieldDescribe.getType() != Schema.DisplayType.MULTISELECTPICKLIST) {
            throw new PicklistServiceException(
                'Field \'' + fieldApiName + '\' is not a picklist or multi-select picklist.'
            );
        }

        List<Option> options = new List<Option>();
        List<Schema.DescribeFieldResult.PicklistValue> picklistValues =
            fieldDescribe.getPicklistValues();

        for (Schema.DescribeFieldResult.PicklistValue pv : picklistValues) {
            if (pv.isValid()) {
                options.add(new Option(pv.getValue(), pv.getLabel(), pv.isDefault()));
            }
        }

        return options;
    }

    private static Schema.SObjectField findFieldCaseInsensitive(
        Map<String, Schema.SObjectField> fieldsMap,
        String fieldApiName
    ) {
        for (String key : fieldsMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                return fieldsMap.get(key);
            }
        }
        return null;
    }
