public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        setMode(fflib_SObjectSelector.MODE.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Set<String> fieldNames = new Set<String>{
            Account.Id.getDescribe().getName(),
            Account.Name.getDescribe().getName(),
            Account.Industry.getDescribe().getName()
        };

        DescribeFieldSetResult creditReview = Account.SObjectType.getDescribe().getFieldSet('Credit_Review');
        if (creditReview != null) {
            for (DescribeFieldSetItemResult item : creditReview.getFields()) {
                Schema.SObjectField field = item.getField();
                if (field == null) {
                    continue;
                }

                String fieldName = field.getDescribe().getName();
                if (!fieldNames.add(fieldName)) {
                    continue;
                }
                fields.add(field);
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        AccountsSelector selector = new AccountsSelector();
        selector.addChildSelect(new ContactsSelector());
        return (List<Account>) selector.selectSObjectsById(accountIds);
    }
}
