    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Set<String> fieldNames = new Set<String>{
            Account.Id.getDescribe().getName(),
            Account.Name.getDescribe().getName(),
            Account.Industry.getDescribe().getName()
        };

        DescribeFieldSetResult creditReview = Account.SObjectType.getDescribe().getFieldSet('Credit_Review');
        if (creditReview != null) {
