```apex
public with sharing class ContactEmailMatcher {

    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;
    }

    @InvocableMethod(label='Match Contact by Email')
    public static List<Result> match(List<Request> requests) {
        List<Result> results = new List<Result>(requests.size());

        // Normalise every email (trim + lowercase); blank becomes null
        Set<String> uniqueEmails = new Set<String>();
        List<String> normalisedInOrder = new List<String>();

        for (Request req : requests) {
            String norm = String.isBlank(req.email) ? null : req.email.trim().toLowerCase();
            normalisedInOrder.add(norm);
            if (norm != null) {
                uniqueEmails.add(norm);
            }
        }

        // Single SOQL – fetch all matching contacts ordered so the first per email wins
        Map<String, Id> emailToContactId = new Map<String, Id>();

        if (!uniqueEmails.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :uniqueEmails
                ORDER BY CreatedDate ASC, Id ASC
            ];

            for (Contact c : contacts) {
                String key = c.Email.trim().toLowerCase();
                if (!emailToContactId.containsKey(key)) {
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        // Build results preserving the original request order
        for (Integer i = 0; i < requests.size(); i++) {
            Result r = new Result();
            String norm = normalisedInOrder.get(i);
            if (norm != null) {
                r.contactId = emailToContactId.get(norm);
            }
            results.add(r);
        }

        return results;
    }
}
