import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    @track results = [];
    @track errorMessage = '';

    debounceTimer = null;
    requestId = 0;
    connected = true;

    connectedCallback() {
        this.connected = true;
    }

    disconnectedCallback() {
        this.connected = false;
        if (this.debounceTimer !== null) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = null;
        }
        // Invalidate any in-flight response
        this.requestId++;
    }

    handleChange(event) {
        const value = event.target.value;

        // Clear any existing debounce timer
        if (this.debounceTimer !== null) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = null;
        }

        const trimmed = value.trim();

        if (trimmed.length < 2) {
            // Cancel any pending search, clear results
            this.requestId++;
            this.results = [];
            this.errorMessage = '';
            return;
        }

        // Debounce: fire the search 300 ms after the last keystroke
        this.debounceTimer = setTimeout(() => {
            this.debounceTimer = null;
            this.performSearch(trimmed);
        }, 300);
    }

    async performSearch(term) {
        const currentRequestId = ++this.requestId;
        this.errorMessage = '';

        try {
            const contacts = await searchContacts({ searchTerm: term });

            if (currentRequestId === this.requestId && this.connected) {
                this.results = contacts || [];
            }
        } catch (error) {
            if (currentRequestId === this.requestId && this.connected) {
                this.errorMessage = error.body.message;
                this.results = [];
            }
        }
    }
}
