```apex
public class EmployerService {

    /**
     * Sets the current employer (Organization account) for a batch of contacts using the
     * standard NPSP affiliation mechanism.
     *
     * For each entry in the map:
     *   - A new Current, primary Hsp_Affiliation__c is created between the contact and
     *     the organization (unless that org is already the contact's primary).
     *   - NPSP's standard trigger on Hsp_Affiliation__c automatically:
         *     • points Contact.Primary_Affiliation__c to the new record,
         *     • sets the previous primary affiliation to Former / non-primary with
         *       End_Date__c = today.
     *   - The contact's HouseholdAccount is never touched, so the household stays intact.
     *
     * SOQL budget: 1 of 2  |  DML budget: 1 of 2
     *
     * @param employerByContactId  Contact Id → Organization Account Id
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // ---- SOQL 1 (of 2): existing primary affiliations for these contacts ----
        Map<Id, Hsp_Affiliation__c> primaryAffByContact =
            new Map<Id, Hsp_Affiliation__c>();
        for (Hsp_Affiliation__c aff : [
            SELECT Id,
                   Contact__c,
                   Account__c,
                   Is_Primary__c
            FROM Hsp_Affiliation__c
            WHERE Contact__c IN :contactIds
              AND Is_Primary__c = true
        ]) {
            primaryAffByContact.put(aff.Contact__c, aff);
        }

        // ---- Determine which contacts actually need a new affiliation ----
        List<Hsp_Affiliation__c> newAffiliations = new List<Hsp_Affiliation__c>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }

            // Skip if this org is already the contact's primary affiliation
            Hsp_Affiliation__c existingPrimary = primaryAffByContact.get(contactId);
            if (existingPrimary != null && existingPrimary.Account__c == orgId) {
                continue;
            }

            newAffiliations.add(
                new Hsp_Affiliation__c(
                    Contact__c    = contactId,
                    Account__c    = orgId,
                    Is_Primary__c = true,
                    Type__c       = 'Current',
                    Start_Date__c = Date.today()
                )
            );
        }

        // ---- DML 1 (of 2): insert the new primary affiliations ----
        //
        // NPSP's standard after-insert trigger on Hsp_Affiliation__c will:
        //   1. Update Contact.Primary_Affiliation__c → the new record
        //   2. Set the previous primary:
        //        Is_Primary__c = false
        //        End_Date__c   = today
        //        Type__c       = 'Former'
        //
        // The contact's HouseholdAccount is never modified, so household membership
        // is preserved.
        if (!newAffiliations.isEmpty()) {
            insert newAffiliations;
        }
    }
}
