public class EmployerService {

    /**
     * Sets the primary employer (Organization Account) for a batch of Contacts.
     *
     * For each Contact whose primary affiliation is changing, the Contact's
     * Primary_Affiliation__c lookup is updated. NPSP's standard trigger/flow on
     * Contact handles the rest of the bookkeeping:
     *   – creates (or promotes) a Current, primary NpspAffiliation__c,
     *   – demotes the previous primary to Former with End_Date__c = TODAY,
     *   – leaves the Contact's Household Account untouched.
     *
     * If the Organization is already the Contact's primary affiliation the
     * record is skipped (no duplicate affiliation is created).
     *
     * SOQL usage: 1 query (Contact lookup).
     * DML usage:  1 statement (bulk update of Contacts).
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // ── 1 SOQL: fetch each Contact's current primary affiliation ─────────
        Map<Id, Id> currentPrimaryByContactId = new Map<Id, Id>();
        for (Contact c : [
            SELECT Id, Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
        ]) {
            currentPrimaryByContactId.put(c.Id, c.Primary_Affiliation__c);
        }

        // ── Build the list of Contacts that actually need to change ──────────
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Id contactId : employerByContactId.keySet()) {
            Id newEmployerId = employerByContactId.get(contactId);
            Id currentPrimaryId = currentPrimaryByContactId.get(contactId);

            // Skip when the employer is already the primary (no-op requirement)
            if (currentPrimaryId != newEmployerId) {
                contactsToUpdate.add(new Contact(
                    Id = contactId,
                    Primary_Affiliation__c = newEmployerId
