            if (req == null) {
                throw new RecurringGiftException('GiftRequest must not be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Contact ID must not be null.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Amount must be a positive number.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Start date must not be null.');
            }
        }

        // Build Enhanced Recurring Donation records (no Opportunity creation – NPSP handles installments)
        List<npe03__Recurring_Donation__c> erps = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c erp = new npe03__Recurring_Donation__c();

            // Donor
            erp.npe03__Contact__c = req.contactId;

            // Amount per installment
            erp.npe03__Amount__c = req.amount;

            // Schedule: monthly on the given day, starting on startDate
            erp.npe03__Start_Date__c = req.startDate;
            erp.npe03__Recurring_Frequency__c = 'Monthly';
            erp.npe03__Recurring_Frequency_Period__c = 1;
            // 31 maps to NPSP's "Last Day of Month" picklist value; 29/30 are stored as-is
            erp.npe03__Recurring_Day__c = String.valueOf(req.dayOfMonth);

            // Status
            erp.npe03__Status__c = 'Active';

            // Payment method
            erp.npe03__Payment_Method__c = req.paymentMethod;

            // Recurring type
            erp.npe03__Recurring_Donation_Type__c = 'Recurring';

            // Fixed-length vs open-ended
            if (req.installments != null && req.installments > 0) {
                erp.npe03__Number_Of_Installments__c = req.installments;
            }

            erps.add(erp);
        }

        // Single bulk DML
        insert erps;

        // Return Ids in request order
        List<Id> ids = new List<Id>();
        for (npe03__Recurring_Donation__c erp : erps) {
            ids.add(erp.Id);
        }
        return ids;
    }
}
