     * @param members  New Contact records (no Id, no AccountId). Must not be null or empty.
     * @return  The Id of the newly created Household Account.
     * @throws IllegalArgumentException  if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }

        // Resolve the Household Account record type at runtime (no hard-coded Id).
        RecordType householdRT = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
              AND Name = 'Household Account'
            LIMIT 1
        ];

        // Create the household. Leave Name unset so NPSP's auto-naming
        // (trigger/flow on Contact insert) generates it.
        Account household = new Account(
            RecordTypeId       = householdRT.Id,
            npe01__Auto_Named__c = true
        );
        insert household;

        // Link every contact to the new household.
        for (Contact c : members) {
            c.AccountId = household.Id;
        }

        // Designate the first contact as the household primary.
        members[0].npe01__Is_Primary__c = true;

        // Bulk-insert all contacts in a single DML statement.
        insert members;

        return household.Id;
    }
}
