public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---- Gather unique opportunity IDs ----
        Set<Id> oppIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) {
                oppIds.add(req.opportunityId);
            }
        }

        // ---- SOQL 1: Opportunities (for validation) ----
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, npsp__Primary_Contact__c, Amount
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // ---- Validate entire batch before any DML ----
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + req.opportunityId);
            }
            if (req.amount == null) {
                throw new SoftCreditException(
                    'Amount cannot be null for opportunity ' + req.opportunityId
                    + ' contact ' + req.contactId);
            }
            if (req.amount <= 0) {
                throw new SoftCreditException(
                    'Amount must be positive for opportunity ' + req.opportunityId
                    + ' contact ' + req.contactId);
            }
            if (req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount ' + req.amount + ' exceeds opportunity amount '
                    + opp.Amount + ' for opportunity ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c != null
                && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId
                    + ' is the primary contact of opportunity ' + req.opportunityId
                    + ' and cannot receive a soft credit.');
            }
        }

        // ---- Build opportunity→contacts lookup for SOQL filtering ----
        Map<Id, Set<Id>> oppToContacts = new Map<Id, Set<Id>>();
        for (SoftCreditRequest req : requests) {
            if (!oppToContacts.containsKey(req.opportunityId)) {
                oppToContacts.put(req.opportunityId, new Set<Id>());
            }
            oppToContacts.get(req.opportunityId).add(req.contactId);
        }

        // ---- SOQL 2: Existing OpportunityContactRoles ----
        Map<String, OpportunityContactRole> existingOcrByPair =
            new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
        ]) {
            if (oppToContacts.containsKey(ocr.OpportunityId)
                && oppToContacts.get(ocr.OpportunityId).contains(ocr.ContactId)) {
                existingOcrByPair.put(
                    ocr.OpportunityId + '|' + ocr.ContactId, ocr);
            }
        }

        // ---- SOQL 3: Existing Partial Soft Credits ----
        Map<String, npsp__Partial_Soft_Credit__c> existingPspcByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c pspc : [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Amount__c,
                   npsp__Role__c,
                   npsp__OpportunityContactRole__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
        ]) {
            if (oppToContacts.containsKey(pspc.npsp__Opportunity__c)
                && oppToContacts.get(pspc.npsp__Opportunity__c)
                       .contains(pspc.npsp__Contact__c)) {
                existingPspcByPair.put(
                    pspc.npsp__Opportunity__c + '|' + pspc.npsp__Contact__c,
                    pspc);
            }
        }

        // ---- Determine OCR insert / update lists ----
        Map<String, OpportunityContactRole> newOcrsByPair =
            new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        Map<String, Id> ocrIdByPair = new Map<String, Id>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            OpportunityContactRole existingOcr = existingOcrByPair.get(key);

            if (existingOcr != null) {
                existingOcr.Role = req.role;
                ocrsToUpdate.add(existingOcr);
                ocrIdByPair.put(key, existingOcr.Id);
            } else {
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId     = req.contactId,
                    Role          = req.role
                );
                newOcrsByPair.put(key, newOcr);
            }
        }

        // ---- DML 1: Insert new OpportunityContactRoles ----
        if (!newOcrsByPair.isEmpty()) {
            insert new List<OpportunityContactRole>(newOcrsByPair.values());
            for (String key : newOcrsByPair.keySet()) {
                ocrIdByPair.put(key, newOcrsByPair.get(key).Id);
            }
        }

        // ---- DML 2: Update existing OpportunityContactRoles ----
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }

        // ---- Determine PSPC insert / update lists ----
        List<npsp__Partial_Soft_Credit__c> pspcsToInsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pspcsToUpdate =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '|' + req.contactId;
            Id ocrId = ocrIdByPair.get(key);

            npsp__Partial_Soft_Credit__c existingPspc = existingPspcByPair.get(key);
            if (existingPspc != null) {
                existingPspc.npsp__Amount__c = req.amount;
                existingPspc.npsp__Role__c = req.role;
                existingPspc.npsp__OpportunityContactRole__c = ocrId;
                pspcsToUpdate.add(existingPspc);
            } else {
                npsp__Partial_Soft_Credit__c newPspc =
                    new npsp__Partial_Soft_Credit__c(
