            if (req.amount == null) {
                throw new SoftCreditException('Amount is null for opportunity ' + req.opportunityId + ' and contact ' + req.contactId);
            }
            if (req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive for opportunity ' + req.opportunityId + ' and contact ' + req.contactId);
            }
            if (req.amount > opp.Amount) {
                throw new SoftCreditException('Amount exceeds opportunity amount for opportunity ' + req.opportunityId + ' and contact ' + req.contactId);
            }
