            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contact == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        // ── Household members ───────────────────────────────────────────────────
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :contact.AccountId
        ];

        // ── Build opportunity name: "FirstName LastName Donation yyyy-MM-dd" ───
        String fName = String.valueOf(contact.FirstName);
        String lName = String.valueOf(contact.LastName);
        String oppName = fName + ' ' + lName + ' Donation ' + giftDate.format('yyyy-MM-dd');

        // ── Create Opportunity ──────────────────────────────────────────────────
        Opportunity opp = new Opportunity(
            Name        = oppName,
            StageName   = 'Closed Won',
            CloseDate   = giftDate,
            Amount      = amount,
            AccountId   = contact.AccountId,
            Type        = 'Donation',
            Primary__c  = contact.Id
        );
        insert opp;

        // ── Contact Roles ───────────────────────────────────────────────────────
        List<ContactRole> contactRoles = new List<ContactRole>();

        // Primary donor
        ContactRole donorCR = new ContactRole(
            ContactId     = contact.Id,
            OpportunityId = opp.Id,
            IsPrimary     = true,
            Title         = 'Donor'
        );
        contactRoles.add(donorCR);

        // Every other household member
        for (Contact member : householdMembers) {
            if (member.Id == contact.Id) {
                continue;
            }
            contactRoles.add(new ContactRole(
                ContactId     = member.Id,
                OpportunityId = opp.Id,
                IsPrimary     = false,
                Title         = 'Household Member'
            ));
        }

        insert contactRoles;

        // ── NPSP Contact Role wrappers ──────────────────────────────────────────
        List<NPSPOpportunityContactRole__c> npspRoles = new List<NPSPOpportunityContactRole__c>();

        for (ContactRole cr : contactRoles) {
            Boolean isDonor = (cr.ContactId == contact.Id);
            npspRoles.add(new NPSPOpportunityContactRole__c(
                OpportunityContactRoleId = cr.Id,
                Primary__c               = isDonor,
                Donation__c              = isDonor,
                Role__c                  = isDonor ? 'Donor' : 'Household Member'
            ));
        }

        insert npspRoles;

        // ── Payment (exactly one, paid, full amount) ───────────────────────────
        NPSPOpportunityContactRole__c donorNpspRole = [
            SELECT Id
            FROM NPSPOpportunityContactRole__c
            WHERE OpportunityContactRoleId = :donorCR.Id
            LIMIT 1
        ];

        Payment__c payment = new Payment__c(
            ContactId                        = contact.Id,
            Amount__c                        = amount,
            Status__c                        = 'Paid',
            Date__c                          = giftDate,
            DatePaid__c                      = giftDate,
            OpportunityId                    = opp.Id,
            NPSPOpportunityContactRoleId__c  = donorNpspRole.Id
        );
        insert payment;

        return opp.Id;
    }
}
