        // only the specific pairs we care about, not every A×B combination.
        Set<String> validPairKeys = new Set<String>();
        for (Id childId : validPairs.keySet()) {
            Id parentId = validPairs.get(childId);
            validPairKeys.add(childId + '|' + parentId);
            validPairKeys.add(parentId + '|' + childId);
        }

        // ---- 1 SOQL query: find any existing relationship between our pairs ----
        Set<String> existingKeys = new Set<String>();
        for (npsp__HHRelationship__c rel : [
            SELECT npsp__Contact_A__c, npsp__Contact_B__c
            FROM npsp__HHRelationship__c
            WHERE (npsp__Contact_A__c IN :childIds AND npsp__Contact_B__c IN :parentIds)
