        // Build new relationship records for pairs that do NOT yet have one
        List<npsp__HHRelationship__c> newRels = new List<npsp__HHRelationship__c>();
        for (Map.Entry<Id, Id> entry : validPairs.entrySet()) {
            Id childId  = entry.getKey();
            Id parentId = entry.getValue();

            // Skip if a relationship already exists in either direction
            if (existingKeys.contains(childId + '|' + parentId)
             || existingKeys.contains(parentId + '|' + childId)) {
                continue;
