/**
 * OPP_MajorGiftFollowUp_TDTM
 *
 * NPSP Table-Driven Trigger Management (TDTM) handler for Opportunity.
 * Registered via NPSP Settings > Trigger Configuration:
 *   Class          : OPP_MajorGiftFollowUp_TDTM
 *   Object         : Opportunity
 *   Trigger Action : AfterInsert;AfterUpdate
 *   Load Order     : 5
 *   Async          : No
 *
 * Creates a high-priority "thank-you call" Task when an Opportunity first
 * qualifies as a major gift (Closed Won AND Amount >= 5000).
 *
 * Bulk-safe: processes any number of records with 0 SOQL and at most 1 DML.
 */
public class OPP_MajorGiftFollowUp_TDTM extends npe01__TriggerHandler {

    public OPP_MajorGiftFollowUp_TDTM() {
        // no-arg constructor required by the TDTM dispatcher
    }

    // Synchronous handler – the admin configured "not asynchronous"
    public override Boolean isAsync() {
        return false;
    }

    // Called by npe01__TriggerDispatcher when the Trigger Handler record is active
    public override void execute() {
        List<Task> tasksToInsert = new List<Task>();

        if (Trigger.isInsert) {
            for (Opportunity opp : Trigger.new) {
                if (isMajorGift(opp)) {
                    tasksToInsert.add(buildTask(opp));
                }
            }
        }

        if (Trigger.isUpdate) {
            for (Integer i = 0; i < Trigger.new.size(); i++) {
                Opportunity newOpp = Trigger.new[i];
                Opportunity oldOpp = Trigger.old[i];

                // Qualify only on the transition INTO a major gift:
                // new state is (Closed Won AND >= 5000) AND old state was NOT
                Boolean nowQualifies  = isMajorGift(newOpp);
                Boolean previouslyQualified = isMajorGift(oldOpp);

                if (nowQualifies && !previouslyQualified) {
                    tasksToInsert.add(buildTask(newOpp));
                }
            }
        }

        // Single DML statement for the entire transaction
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }

    /**
     * Returns true when the opportunity meets both criteria:
     *   Status == 'Closed Won'  AND  Amount >= 5000
     */
    private static Boolean isMajorGift(Opportunity opp) {
        return opp.Status == 'Closed Won'
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

    /**
     * Builds the follow-up Task for a qualifying opportunity.
     */
    private static Task buildTask(Opportunity opp) {
        return new Task(
            Subject      = 'Major gift thank-you call',
            Priority     = 'High',
            Status       = 'Not Started',
            WhatId       = opp.Id,
            WhoId        = opp.npsp__Primary_Contact__c,  // may be null
            OwnerId      = opp.OwnerId,
            ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
        );
    }
}
```

