/**
 * TDTM Trigger Handler – Major Gift Follow-Up
 *
 * Creates a single follow-up Task whenever an Opportunity is a "major gift"
 * (StageName = Closed Won, Amount >= 5000) that is either:
 *   • inserted in that state, or
 *   • updated into that state from a non-qualifying prior state.
 *
 * Register in NPSP Settings › Trigger Configuration:
 *   Class          : OPP_MajorGiftFollowUp_TDTM
 *   Object         : Opportunity
 *   Trigger Action : AfterInsert;AfterUpdate
 *   Load Order     : 5
 *   Asynchronous   : No
 *
 * Bulk-safe: 0 SOQL queries, ≤ 1 DML statement per trigger invocation.
 */
public class OPP_MajorGiftFollowUp_TDTM extends H_TDTM_HandlingClass {

    public OPP_MajorGiftFollowUp_TDTM() {
        super('Opportunity');
    }

    // ─────────────────────────────────────────────────────────────────────
    // AfterInsert
    // ─────────────────────────────────────────────────────────────────────
    override public void handleAfterInsert(List<SObject> newRecs) {
        List<Opportunity> opportunities = (List<Opportunity>) newRecs;
        List<Task> tasks = new List<Task>();

        for (Opportunity opp : opportunities) {
            if (isMajorGift(opp)) {
                tasks.add(buildTask(opp));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }

    // ─────────────────────────────────────────────────────────────────────
    // AfterUpdate
    // ─────────────────────────────────────────────────────────────────────
    override public void handleAfterUpdate(List<SObject> newRecs, Map<Id, SObject> oldRecs) {
        List<Opportunity> newOpportunities = (List<Opportunity>) newRecs;
        Map<Id, Opportunity> oldOpportunities = new Map<Id, Opportunity>();
        for (Id oppId : oldRecs.keySet()) {
            oldOpportunities.put(oppId, (Opportunity) oldRecs.get(oppId));
        }

        List<Task> tasks = new List<Task>();

        for (Opportunity opp : newOpportunities) {
            Opportunity oldOpp = oldOpportunities.get(opp.Id);

            Boolean nowQualified      = isMajorGift(opp);
            Boolean previouslyQualified = (oldOpp != null) && isMajorGift(oldOpp);

            // Only create a task when the gift transitions INTO the major-gift
            // state; editing an already-qualified gift must not create another.
            if (nowQualified && !previouslyQualified) {
                tasks.add(buildTask(opp));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }

    // ─────────────────────────────────────────────────────────────────────
    // Private helpers
    // ─────────────────────────────────────────────────────────────────────

    /**
     * True when the opportunity is a major gift:
     * StageName = 'Closed Won' AND Amount >= 5000.
     */
    private Boolean isMajorGift(Opportunity opp) {
        return opp != null
            && 'Closed Won'.equals(opp.StageName)
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

    /**
     * Builds the follow-up Task for a qualifying major gift.
     */
    private Task buildTask(Opportunity opp) {
        return new Task(
            Subject      = 'Major gift thank-you call',
            Priority     = 'High',
            Status       = 'Not Started',
            WhatId       = opp.Id,
            WhoId        = opp.npsp__Primary_Contact__c,
            OwnerId      = opp.OwnerId,
            ActivityDate = (opp.CloseDate != null) ? opp.CloseDate.addDays(3) : null
        );
    }
}
