File: force-app/main/default/classes/TA_Account_CreateOnboardingTask.cls
```apex
public class TA_Account_CreateOnboardingTask implements TriggerAction {

    /**
     * TAF Trigger Action – create an onboarding Task for qualifying new Accounts.
     *
     * Qualifying types : Customer - Direct, Customer - Channel
     * Operation        : AFTER_INSERT only
     * DML guarantee    : one insert statement for the whole batch; zero DML when
     *                    no account qualifies.
     */
    public void execute(TriggerAction.Context context) {

        // Only react to insert operations
        if (context.triggerOp != TriggerOperation.AFTER_INSERT) {
            return;
        }

        List<Account> newAccounts = (List<Account>) context.newSObject;
        List<Task> tasksToInsert   = new List<Task>();
        Date dueDate               = Date.today().addDays(7);

        for (Account acc : newAccounts) {
            if (acc.Type == 'Customer - Direct' || acc.Type == 'Customer - Channel') {
                tasksToInsert.add(new Task(
                    Subject      = 'Onboard new customer',
                    WhatId       = acc.Id,
                    OwnerId      = acc.OwnerId,
                    ActivityDate = dueDate,
                    Status       = 'Not Started',
                    Priority     = 'Normal'
                ));
            }
        }

        // Single DML statement; skipped entirely when nothing qualifies
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
```

