public class TA_Contact_PreventDuplicateEmail {

    public static void execute() {

        // ------------------------------------------------------------------
        // 1. Collect the AccountIds and Emails we need to check
        // ------------------------------------------------------------------
        Set<Id>    accountIds = new Set<Id>();
        Set<String> emails    = new Set<String>();

        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                accountIds.add(c.AccountId);
                emails.add(c.Email);
            }
        }

        // Nothing to validate
        if (accountIds.isEmpty() || emails.isEmpty()) {
            return;
        }

        // ------------------------------------------------------------------
        // 2. Single SOQL query – find existing contacts that could conflict
        //    (cross-product IN is fine for ≤ 200 records; we filter in Apex)
        // ------------------------------------------------------------------
        Map<String, Set<Id>> dbCombos = new Map<String, Set<Id>>();

        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email IN :emails
        ]) {
            String key = c.AccountId + '_' + String.lowerCase(c.Email);
            if (!dbCombos.containsKey(key)) {
                dbCombos.put(key, new Set<Id>());
            }
            dbCombos.get(key).add(c.Id);
        }

        // ------------------------------------------------------------------
        // 3. Walk the trigger records in order – first valid claim wins
        // ------------------------------------------------------------------
        Set<String> claimed = new Set<String>();   // keys already taken in this batch

        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Contact c = Trigger.new[i];

            // Skip contacts with no Account or no Email
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            // On update, only re-check contacts whose Email or AccountId changed
            if (Trigger.isUpdate) {
                Contact oldC = Trigger.old[i];
                if (c.Email == oldC.Email && c.AccountId == oldC.AccountId) {
                    continue;
                }
            }

            String key = c.AccountId + '_' + String.lowerCase(c.Email);

            // 3a. Already claimed earlier in this batch?
            if (claimed.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
                continue;
            }

            // 3b. Exists in the database? (exclude self for safety)
            if (dbCombos.containsKey(key)) {
                Set<Id> existingIds = dbCombos.get(key);
                boolean conflict = false;
                for (Id existingId : existingIds) {
                    if (existingId != c.Id) {
                        conflict = true;
                        break;
                    }
                }
                if (conflict) {
                    c.addError('Another contact on this account already uses this email address.');
                    continue;
                }
            }

            // No conflict – claim this account+email combination for the batch
            claimed.add(key);
        }
    }
}
