public class TA_Contact_PreventDuplicateEmail implements Trigger_Action_Interface {

    private List<Contact> newContacts;
    private List<Contact> oldContacts;
    private Boolean isUpdate;

    public TA_Contact_PreventDuplicateEmail(List<Contact> newContacts) {
        this.newContacts = newContacts;
        this.isUpdate = false;
    }

    public TA_Contact_PreventDuplicateEmail(List<Contact> newContacts, List<Contact> oldContacts) {
        this.newContacts = newContacts;
        this.oldContacts = oldContacts;
        this.isUpdate = true;
    }

    public void execute() {
        Map<Id, Contact> oldMap = new Map<Id, Contact>();
        if (isUpdate) {
            for (Contact oc : oldContacts) {
                oldMap.put(oc.Id, oc);
            }
        }

        Set<Id> idsToExclude = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        List<Integer> indicesToCheck = new List<Integer>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];

            // Skip contacts without an Account or without an Email
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            // On update, only check contacts whose Email or AccountId changed
            if (isUpdate) {
                Contact oldC = oldMap.get(c.Id);
                if (oldC != null && c.Email == oldC.Email && c.AccountId == oldC.AccountId) {
                    continue;
                }
                idsToExclude.add(c.Id);
            }

            indicesToCheck.add(i);
            accountIds.add(c.AccountId);
        }

        if (indicesToCheck.isEmpty()) {
            return;
        }

        // Single SOQL query: fetch all existing contacts on the relevant accounts
        List<Contact> existingContacts;
        if (isUpdate) {
            existingContacts = [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email != null
                  AND Id NOT IN :idsToExclude
            ];
        } else {
            existingContacts = [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email != null
            ];
        }

        // Build lookup: "AccountId|lowercaseEmail" -> true
        Map<String, Boolean> existingEmails = new Map<String, Boolean>();
        for (Contact ec : existingContacts) {
            String key = ec.AccountId + '|' + ec.Email.toLowerCase();
            existingEmails.put(key, true);
        }

        // Process in Trigger.new order: first wins, later duplicates get errors
        Set<String> batchEmails = new Set<String>();
        for (Integer idx : indicesToCheck) {
            Contact c = newContacts[idx];
            String key = c.AccountId + '|' + c.Email.toLowerCase();

            if (existingEmails.containsKey(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else if (batchEmails.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                batchEmails.add(key);
            }
        }
    }
}
