        this.newContacts = newContacts;
        this.oldContacts = oldContacts;
        this.isUpdate = isUpdate;
    }

    public void execute() {
        // Determine which contacts to check
        List<Integer> checkIndices = new List<Integer>();
        Map<Id, Contact> oldMap = null;

        if (isUpdate) {
            oldMap = new Map<Id, Contact>(oldContacts);
        }

        Set<Id> idsToExclude = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];

            // Skip if no Account or no Email
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            if (isUpdate) {
                Contact oldC = oldMap.get(c.Id);
                Boolean emailChanged = (c.Email != oldC.Email); // handles null vs non-null
                Boolean accountIdChanged = (c.AccountId != oldC.AccountId);

                if (!emailChanged && !accountIdChanged) {
                    continue;
                }
            }

            checkIndices.add(i);
            idsToExclude.add(c.Id);
            accountIds.add(c.AccountId);
        }

        if (checkIndices.isEmpty()) {
            return;
        }

        // Query existing contacts
        // For insert: no exclusions needed (new records aren't in DB yet)
        // For update: exclude the ids being checked (they don't conflict with themselves)
        List<Contact> existing;
        if (isUpdate) {
            existing = [SELECT Id, AccountId, Email FROM Contact 
                        WHERE AccountId IN :accountIds 
                        AND Email != null 
                        AND Id NOT IN :idsToExclude];
        } else {
            existing = [SELECT Id, AccountId, Email FROM Contact 
                        WHERE AccountId IN :accountIds 
                        AND Email != null];
        }

        // Build map: key = AccountId|LOWER(Email) -> Set of Ids
        Map<String, Set<Id>> existingMap = new Map<String, Set<Id>>();
        for (Contact ec : existing) {
            String key = ec.AccountId + '|' + ec.Email.toLowerCase();
            if (!existingMap.containsKey(key)) {
                existingMap.put(key, new Set<Id>());
            }
            existingMap.get(key).add(ec.Id);
        }

        // Process in order
        Set<String> batchKeys = new Set<String>();
        for (Integer i : checkIndices) {
            Contact c = newContacts[i];
            String key = c.AccountId + '|' + c.Email.toLowerCase();

            if (existingMap.containsKey(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else if (batchKeys.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                batchKeys.add(key);
            }
        }
    }
}
