public class TA_Case_RollupOpenCount extends Trigger_Action {

    public override void process() {
        Set<Id> affectedAccountIds = new Set<Id>();
        Map<Id, Integer> deltas = new Map<Id, Integer>();

        if (triggerType == 'After Insert') {
            for (Case c : (List<Case>) triggerNew.values()) {
                if (c.AccountId != null && c.IsClosed == false) {
                    affectedAccountIds.add(c.AccountId);
                    deltas.put(c.AccountId, deltas.getOrDefault(c.AccountId, 0) + 1);
                }
            }
        }
        else if (triggerType == 'After Update') {
            for (Id id : triggerNew.keySet()) {
                Case newCase = (Case) triggerNew.get(id);
                Case oldCase = (Case) triggerOld.get(id);

                if (newCase.AccountId != oldCase.AccountId) {
                    // Account changed – adjust both old and new accounts
                    if (oldCase.AccountId != null && oldCase.IsClosed == false) {
                        affectedAccountIds.add(oldCase.AccountId);
                        deltas.put(oldCase.AccountId, deltas.getOrDefault(oldCase.AccountId, 0) - 1);
                    }
                    if (newCase.AccountId != null && newCase.IsClosed == false) {
                        affectedAccountIds.add(newCase.AccountId);
                        deltas.put(newCase.AccountId, deltas.getOrDefault(newCase.AccountId, 0) + 1);
                    }
                }
                else if (newCase.AccountId != null && oldCase.IsClosed != newCase.IsClosed) {
                    // Same account, open/closed status changed
                    affectedAccountIds.add(newCase.AccountId);
                    if (newCase.IsClosed == false) {
                        // Reopened
                        deltas.put(newCase.AccountId, deltas.getOrDefault(newCase.AccountId, 0) + 1);
                    }
                    else {
                        // Closed
                        deltas.put(newCase.AccountId, deltas.getOrDefault(newCase.AccountId, 0) - 1);
                    }
                }
            }
        }
        else if (triggerType == 'After Delete') {
            for (Case c : (List<Case>) triggerOld.values()) {
                if (c.AccountId != null && c.IsClosed == false) {
                    affectedAccountIds.add(c.AccountId);
                    deltas.put(c.AccountId, deltas.getOrDefault(c.AccountId, 0) - 1);
                }
            }
        }
        else if (triggerType == 'After Undelete') {
            for (Case c : (List<Case>) triggerNew.values()) {
                if (c.AccountId != null && c.IsClosed == false) {
                    affectedAccountIds.add(c.AccountId);
                    deltas.put(c.AccountId, deltas.getOrDefault(c.AccountId, 0) + 1);
                }
            }
        }

        if (affectedAccountIds.isEmpty()) {
            return;
        }

        // SOQL query 1 – fetch current counts for all affected accounts
        Map<Id, Account> accounts = new Map<Id, Account>(
            [SELECT Id, FB_Open_Case_Count__c FROM Account WHERE Id IN :affectedAccountIds]
        );

        // Build the update list
        List<Account> toUpdate = new List<Account>();
        for (Id accId : affectedAccountIds) {
            Account acc = accounts.get(accId);
            if (acc == null) {
                continue;
            }
            Integer current = (acc.FB_Open_Case_Count__c == null) ? 0 : acc.FB_Open_Case_Count__c.intValue();
