public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    // Tracks which Opportunity Ids have already been audited in this transaction.
    // Persists across re-entrant trigger calls (e.g., the rounding action's DML),
    // guaranteeing at most one "Amount changed" Task per opportunity per transaction.
    private static Set<Id> auditedIds;

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        if (auditedIds == null) {
            auditedIds = new Set<Id>();
        }

        List<Task> tasks = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            if (newOpp.Amount != oldOpp.Amount
                    && !auditedIds.contains(newOpp.Id)) {
                auditedIds.add(newOpp.Id);
                tasks.add(new Task(
                    Subject  = 'Amount changed',
                    WhatId   = newOpp.Id,
                    Status   = 'Completed'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
