    private static Set<Id> loggedOppIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasks = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            // Amount changed (covers null→value, value→null, value→different value)
            if (newOpp.Amount != oldOpp.Amount) {
                // Guard: at most one task per Opportunity per transaction
                if (!loggedOppIds.contains(newOpp.Id)) {
                    loggedOppIds.add(newOpp.Id);
                    tasks.add(new Task(
                        Subject  = 'Amount changed',
                        WhatId   = newOpp.Id,
                        Status   = 'Completed'
                    ));
                }
            }
        }

        // One DML statement regardless of how many opportunities changed
        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
