public class CasePriorityHandler {

    /**
     * For every new Case whose Account.Rating = 'Hot', set Priority to 'High'.
     * All other cases retain the Priority they were created with.
     *
     * Bulk-safe: a single SOQL is issued regardless of the number of cases,
     * so a 200-case ERP batch still costs one query.
     */
    public static void handleInsert(List<Case> newCases) {

        // 1. Collect the unique AccountIds we actually need to look up.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // Nothing to do if no case carries an AccountId.
        if (accountIds.isEmpty()) {
            return;
        }

        // 2. One SOQL for every account we need (≤ 1 query per transaction).
        Map<Id, String> ratingByAccountId = new Map<Id, String>();
        for (Account acc : [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]) {
            ratingByAccountId.put(acc.Id, acc.Rating);
        }

        // 3. Apply the rule in memory – no extra DML or queries.
        for (Case c : newCases) {
            if (c.AccountId != null
                    && ratingByAccountId.get(c.AccountId) == 'Hot') {
                c.Priority = 'High';
            }
            // else: leave Priority as-is (covers 'Warm', 'Cold', null, no account)
        }
    }
}
```

