public class CasePriorityHandler {

    /**
     * Bump Priority to 'High' for cases whose parent Account is rated 'Hot'.
     * All other cases (including those without an Account) keep the Priority
     * they were created with.
     *
     * @param newCases  List of Case records being inserted (Trigger.new).
     */
    public static void handle(List<Case> newCases) {

        // 1. Collect every distinct AccountId so we can fetch them in ONE query.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // 2. Single SOQL – safe for batches up to 200 (or more).
        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        // 3. Apply the rule.
        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue; // no account – keep whatever Priority was set
            }

            Account acc = accountMap.get(c.AccountId);
            if (acc != null && acc.Rating == 'Hot') {
                c.Priority = 'High';
            }
            // Otherwise the existing Priority is left as-is.
        }
    }
}
```

