        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }

        // Build PSC records now that all OCR Ids are known
        List<npsp__Partial_Soft_Credit__c> pscsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests.get(i);
            OpportunityContactRole ocr = reqOcrMap.get(i);
            String pscKey = req.opportunityId + '|' + req.contactId;
            npsp__Partial_Soft_Credit__c existingPsc = pscMap.get(pscKey);

            if (existingPsc != null) {
                existingPsc.npsp__Amount__c = req.amount;
                existingPsc.npsp__Role_Name__c = req.role;
                existingPsc.npsp__Contact_Role_ID__c = String(ocr.Id);
                pscsToUpdate.add(existingPsc);
