```
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_AMOUNT_THRESHOLD = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer TASK_ACTIVITY_OFFSET_DAYS = 3;

    public override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist, List<SObject> oldlist, npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {
        if (triggerAction == null || newlist == null || newlist.isEmpty()) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        Boolean isInsert = triggerAction == npsp.TDTM_Runnable.Action.AFTER_INSERT;
        Boolean isUpdate = triggerAction == npsp.TDTM_Runnable.Action.AFTER_UPDATE;
        if (!isInsert && !isUpdate) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        Map<Id, Opportunity> oldOpps = new Map<Id, Opportunity>();
        if (isUpdate && oldlist != null) {
            for (SObject sObject : oldlist) {
                if (sObject instanceof Opportunity) {
                    Opportunity opp = (Opportunity) sObject;
                    oldOpps.put(opp.Id, opp);
                }
            }
        }

        List<Task> tasksToInsert = new List<Task>();
        Set<Id> seenIds = new Set<Id>();

        for (SObject sObject : newlist) {
            if (!(sObject instanceof Opportunity)) {
                continue;
            }
            Opportunity opp = (Opportunity) sObject;
            if (opp.Id == null || !seenIds.add(opp.Id)) {
                continue;
            }

            if (!isMajorGift(opp)) {
                continue;
            }

            if (isInsert) {
                tasksToInsert.add(buildTask(opp));
            } else {
                Opportunity oldOpp = oldOpps.get(opp.Id);
                if (oldOpp == null || !isMajorGift(oldOpp)) {
                    tasksToInsert.add(buildTask(opp));
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return new npsp.TDTM_Runnable.DmlWrapper();
    }

    private static Boolean isMajorGift(Opportunity opp) {
        return opp != null
            && opp.StageName == STAGE_CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_AMOUNT_THRESHOLD;
    }

    private static Task buildTask(Opportunity opp) {
        Date activityDate = (opp.CloseDate != null) ? opp.CloseDate.addDays(TASK_ACTIVITY_OFFSET_DAYS) : Date.today().addDays(TASK_ACTIVITY_OFFSET_DAYS);
        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = activityDate
        );
    }
}
