```
public class OPP_MajorGiftFollowUp_TDTM with sharing extends npsp.TDTM_Runnable {
    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer FOLLOW_UP_DAYS = 3;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        if (newlist == null || newlist.isEmpty() || triggerAction == null) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        Boolean isInsert = triggerAction == npsp.TDTM_Runnable.Action.AFTER_INSERT;
        Boolean isUpdate = triggerAction == npsp.TDTM_Runnable.Action.AFTER_UPDATE;
        if (!isInsert && !isUpdate) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (isUpdate && oldlist != null) {
            for (SObject sObject : oldlist) {
                if (sObject instanceof Opportunity) {
                    Opportunity oldOpp = (Opportunity) sObject;
                    if (oldOpp.Id != null) {
                        oldOppsById.put(oldOpp.Id, oldOpp);
                    }
                }
            }
        }

        List<Task> tasksToInsert = new List<Task>();
        Set<Id> processedOpportunityIds = new Set<Id>();

        for (SObject sObject : newlist) {
            if (!(sObject instanceof Opportunity)) {
                continue;
            }

            Opportunity opp = (Opportunity) sObject;
            if (opp.Id == null || !processedOpportunityIds.add(opp.Id)) {
                continue;
            }

            if (!isMajorGift(opp)) {
                continue;
            }

            if (isInsert) {
                tasksToInsert.add(buildThankYouTask(opp));
            } else {
                Opportunity oldOpp = oldOppsById.get(opp.Id);
                if (oldOpp == null || !isMajorGift(oldOpp)) {
                    tasksToInsert.add(buildThankYouTask(opp));
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return new npsp.TDTM_Runnable.DmlWrapper();
    }

    private static Boolean isMajorGift(Opportunity opp) {
        return opp != null
            && opp.StageName == CLOSED_WON_STAGE
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildThankYouTask(Opportunity opp) {
        Date activityDate = opp.CloseDate != null
            ? opp.CloseDate.addDays(FOLLOW_UP_DAYS)
            : Date.today().addDays(FOLLOW_UP_DAYS);

        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId != null ? opp.OwnerId : UserInfo.getUserId(),
            ActivityDate = activityDate
        );
    }
}
```

