public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    private static final Decimal MAJOR_GIFT_MINIMUM = 5000;
    private static final Date THREE_DAYS = ... // can't static Date? 
    public override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist, List<SObject> oldlist, npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();
        if (newlist == null || newlist.isEmpty()) return dmlWrapper;
        if (!isEligibleAction(triggerAction)) return dmlWrapper;
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (oldlist != null) { for (SObject s : oldlist) oldMap.put(((Opportunity)s).Id, (Opportunity)s); }
        List<Task> tasks = new List<Task>();
        for (SObject sObj : newlist) {
            Opportunity opp = (Opportunity) sObj;
            if (opp.Id == null) continue;
            Boolean newQualified = isQualified(opp);
            if (!newQualified) continue;
            Opportunity oldOpp = oldMap.get(opp.Id);
            Boolean oldQualified = oldOpp != null && isQualified(oldOpp);
            if (oldQualified) continue;
            tasks.add(buildTask(opp));
        }
        if (!tasks.isEmpty()) dmlWrapper.insertList(tasks);
        return dmlWrapper;
    }
    private static Boolean isEligibleAction(npsp.TDTM_Runnable.Action action) {
        if (action == null) return false;
        String actionName = String.valueOf(action);
        return actionName == 'AfterInsert' || actionName == 'AfterUpdate';
    }
    private static Boolean isQualified(Opportunity opp) {
        return opp != null && opp.StageName != null && opp.StageName == 'Closed Won' && opp.Amount != null && opp.Amount >= 5000;
    }
    private static Task buildTask(Opportunity opp) {
        Date activityDate = opp.CloseDate == null ? System.today().addDays(3) : opp.CloseDate.addDays(3);
        return new Task(
            Subject = 'Major gift thank-you call',
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId != null ? opp.OwnerId : UserInfo.getUserId(),
            ActivityDate = activityDate
        );
    }
}
```
