public without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    private static final String CLOSED_WON_STAGE = 'Closed Won';
    private static final Decimal MAJOR_GIFT_MINIMUM = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final Integer ACTIVITY_OFFSET_DAYS = 3;

    public override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist, List<SObject> oldlist, npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();
        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject oldSObject : oldlist) {
                if (oldSObject instanceof Opportunity) {
                    Opportunity oldOpp = (Opportunity) oldSObject;
                    if (oldOpp.Id != null) {
                        oldMap.put(oldOpp.Id, oldOpp);
                    }
                }
            }
        }

        List<Task> tasksToInsert = new List<Task>();
        for (SObject newSObject : newlist) {
            if (!(newSObject instanceof Opportunity)) {
                continue;
            }
            Opportunity opp = (Opportunity) newSObject;
            if (opp.Id == null) {
                continue;
            }
            if (!isMajorGiftClosedWon(opp)) {
                continue;
            }
            Opportunity oldOpp = oldMap.get(opp.Id);
            if (oldOpp != null && isMajorGiftClosedWon(oldOpp)) {
                continue;
            }
            tasksToInsert.add(buildMajorGiftTask(opp));
        }

        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.insertList(tasksToInsert);
        }
        return dmlWrapper;
    }

    private static Boolean isMajorGiftClosedWon(Opportunity opp) {
        return opp != null
            && opp.StageName != null
            && opp.StageName == CLOSED_WON_STAGE
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_MINIMUM;
    }

    private static Task buildMajorGiftTask(Opportunity opp) {
        Date activityDate = opp.CloseDate == null
            ? System.today().addDays(ACTIVITY_OFFSET_DAYS)
            : opp.CloseDate.addDays(ACTIVITY_OFFSET_DAYS);

        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId != null ? opp.OwnerId : UserInfo.getUserId(),
            ActivityDate = activityDate
        );
    }
}
