public class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MSG =
            'Another contact on this account already uses this email address.';

    // ------------------------------------------------------------------
    // Before Insert
    // ------------------------------------------------------------------
    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> eligible = filterEligible(triggerNew, null);
        if (eligible.isEmpty()) {
            return;
        }

        Set<Id> accountIds = collectAccountIds(eligible);

        // Single SOQL: fetch all contacts on the relevant accounts
        Map<String, Boolean> existingKeys = buildExistingKeyMap(accountIds, null);

        // Within-batch "first wins" tracking
        Map<String, Boolean> seenInBatch = new Map<String, Boolean>();

        for (Contact c : eligible) {
            String key = c.AccountId + '|' + c.Email.toUpperCase();

            if (existingKeys.containsKey(key)) {
                c.addError(ERROR_MSG);
                continue;
            }
            if (seenInBatch.containsKey(key)) {
                c.addError(ERROR_MSG);
                continue;
            }
            seenInBatch.put(key, true);
        }
    }

    // ------------------------------------------------------------------
    // Before Update
    // ------------------------------------------------------------------
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> eligible = filterEligible(triggerNew, triggerOld);
        if (eligible.isEmpty()) {
            return;
        }

