                c.addError(ERROR_MSG);
                continue;
            }
            if (seenInBatch.containsKey(key)) {
                c.addError(ERROR_MSG);
                continue;
            }
            seenInBatch.put(key, true);
        }
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    /**
     * Returns only the contacts that should be validated.
     *  - must have non-null AccountId and non-blank Email
     *  - in update context, Email or AccountId must have changed
     */
    private static List<Contact> filterEligible(
            List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> result = new List<Contact>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact c = (Contact) triggerNew.get(i);
            if (c.AccountId == null || String.isBlank(c.Email)) {
