    private static Map<String, Boolean> buildExistingKeyMap(
            Set<Id> accountIds, Set<Id> excludeIds) {
        Map<String, Boolean> keyMap = new Map<String, Boolean>();

        // Build the SOQL with optional NOT IN clause
        String soql = 'SELECT Id, AccountId, Email FROM Contact WHERE AccountId IN :accountIds';
