```apex
public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    /**
     * Before insert: ensure no two contacts in the same save share an account+email,
     * and no new contact collides with an existing contact in the database.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> relevant = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                relevant.add(c);
                accountIds.add(c.AccountId);
            }
        }

        if (relevant.isEmpty()) {
            return;
        }

        // Single SOQL: fetch existing contacts on the same accounts that have an email
        Set<String> existingKeys = new Set<String>();
        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != NULL
        ]) {
            existingKeys.add(buildKey(c.AccountId, c.Email));
        }

        // Track keys already claimed within this batch (first-in-list wins)
        Set<String> batchKeys = new Set<String>();

        for (Contact c : relevant) {
            String key = buildKey(c.AccountId, c.Email);
            if (existingKeys.contains(key) || batchKeys.contains(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                batchKeys.add(key);
            }
        }
    }

    /**
     * Before update: only check contacts whose Email or AccountId changed.
     * A contact never conflicts with itself; legacy duplicates are ignored.
     */
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> relevant = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<Id> updateIds = new Set<Id>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact newC = (Contact) triggerNew.get(i);
            Contact oldC = (Contact) triggerOld.get(i);

            Boolean emailChanged = newC.Email != oldC.Email;
            Boolean accountIdChanged = newC.AccountId != oldC.AccountId;

            if ((emailChanged || accountIdChanged)
                    && newC.AccountId != null
                    && String.isNotBlank(newC.Email)) {
                relevant.add(newC);
                accountIds.add(newC.AccountId);
                updateIds.add(newC.Id);
            }
        }

        if (relevant.isEmpty()) {
            return;
        }

        // Single SOQL: fetch existing contacts on the target accounts, excluding the records being updated
        Set<String> existingKeys = new Set<String>();
        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != NULL
        ]) {
            if (updateIds.contains(c.Id)) {
                continue; // a contact never conflicts with itself
            }
            existingKeys.add(buildKey(c.AccountId, c.Email));
        }

        // Track keys already claimed within this batch (first-in-list wins)
        Set<String> batchKeys = new Set<String>();

        for (Contact c : relevant) {
            String key = buildKey(c.AccountId, c.Email);
            if (existingKeys.contains(key) || batchKeys.contains(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                batchKeys.add(key);
            }
        }
    }

    private static String buildKey(Id accountId, String email) {
        return accountId + '|' + String.lowerCase(email);
    }
}
