        List<Task> tasks = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            // Process only the first after-update pass for this record in the transaction.
            // The rounding action (Order 20) re-updates the same records, causing a second
            // after-update pass; that pass must not create a duplicate audit Task.
            if (TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(newOpp.Id) != 1) {
                continue;
            }

            if (newOpp.Amount != oldOpp.Amount) {
                tasks.add(new Task(
                    Subject  = 'Amount changed',
                    WhatId   = newOpp.Id,
                    Status   = 'Completed'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
