public class TA_Contact_Queries {
    private static TA_Contact_Queries instance;
    public Map<Id, Account> accountsById;

    private TA_Contact_Queries() {
        accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject s : triggerNew) {
                Id accId = (Id) s.get('AccountId');
                if (accId != null) {
                    accountIds.add(accId);
                }
            }

            Map<Id, Account> loadedMap = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                loadedMap = new Map<Id, Account>(
                    [SELECT Id,
                        BillingStreet,
                        BillingCity,
                        BillingPostalCode,
                        BillingCountry,
                        AccountSource
                     FROM Account
                     WHERE Id IN :accountIds]
                );
            }

            TA_Contact_Queries.getInstance().accountsById = loadedMap;
        }
    }
}
